#include "../v7/search.h"
#include "../v7/pool.h"
#include <climits>
using namespace v2;
int main(){try{init();Learner model;model.load("training/v7/base.ntd");auto pool=loadEarlyPool("training/v7/assessment-pool.txt");Search search(model);search.maxNodes=INT_MAX;std::ofstream out("training/diagnosis-v7/context.jsonl");out<<std::setprecision(17);for(int i=0;i<int(pool.states.size());i++){auto&s=pool.states[i];if(s.game.next.bonus)continue;Counts prior=s.counts;prior[s.game.next.cards[0]-1]++;int total=prior[0]+prior[1]+prior[2],kinds=0;for(auto n:prior)kinds+=n>0;if(kinds<2)continue;std::array<std::array<double,4>,3> q{};for(int card=1;card<=3;card++)if(prior[card-1]){Preview p;p.size=1;p.cards[0]=card;p.p[0]=1;Counts c=prior;c[card-1]--;search.choose(s.game.b,p,c,3);if(search.completed!=3)throw std::runtime_error("incomplete");q[card-1]=search.rootValues;}for(int d=0;d<4;d++){auto m=move(s.game.b,d);if(!m.size||high(m.b)>=12)continue;double mean=0,variance=0,lo=1e300,hi=-1e300;for(int card=0;card<3;card++)if(prior[card]){double target=q[card][d]-m.reward;mean+=double(prior[card])/total*target;lo=std::min(lo,target);hi=std::max(hi,target);}for(int card=0;card<3;card++)if(prior[card]){double diff=q[card][d]-m.reward-mean;variance+=double(prior[card])/total*diff*diff;}out<<"{\"source\":"<<i<<",\"direction\":"<<d<<",\"range\":"<<hi-lo<<",\"variance\":"<<variance<<",\"priorCounts\":["<<prior[0]<<','<<prior[1]<<','<<prior[2]<<"],\"targets\":[";for(int card=0;card<3;card++){if(card)out<<',';if(prior[card])out<<q[card][d]-m.reward;else out<<"null";}out<<"]}"<<std::endl;}}}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
